// Valid: no catch, no finally -- the resource is still auto-closed.
public List<String> readLines(String path) throws IOException {
    try (BufferedReader br = new BufferedReader(new FileReader(path))) {
        return br.lines().toList();
    }
    // close() runs automatically; IOException propagates to the caller.
}

// Add catch ONLY if you want to handle it here:
public List<String> readLinesSafe(String path) {
    try (BufferedReader br = new BufferedReader(new FileReader(path))) {
        return br.lines().toList();
    } catch (IOException e) {
        return List.of();   // graceful fallback
    }
}
